import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

argmin_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template<typename T>
__global__ void argmin_dim1_kernel(const T* input, int64_t* output, int batch_size, int dim1, int dim2) {
    const int batch = blockIdx.x;
    const int d2 = blockIdx.y;
    const int tid = threadIdx.x;

    T min_val = INFINITY;
    int min_idx = 0;

    for(int i = tid; i < dim1; i += blockDim.x) {
        T val = input[batch * dim1 * dim2 + i * dim2 + d2];
        if(val < min_val || (val == min_val && i < min_idx)) {
            min_val = val;
            min_idx = i;
        }
    }

    __shared__ T shared_min[256];
    __shared__ int shared_idx[256];

    shared_min[tid] = min_val;
    shared_idx[tid] = min_idx;
    __syncthreads();

    for(int offset = blockDim.x/2; offset > 0; offset >>= 1) {
        if(tid < offset) {
            if(shared_min[tid + offset] < shared_min[tid] || 
               (shared_min[tid + offset] == shared_min[tid] && shared_idx[tid + offset] < shared_idx[tid])) {
                shared_min[tid] = shared_min[tid + offset];
                shared_idx[tid] = shared_idx[tid + offset];
            }
        }
        __syncthreads();
    }

    if(tid == 0) {
        output[batch * dim2 + d2] = shared_idx[0];
    }
}

torch::Tensor argmin_cuda(torch::Tensor input, int dim) {
    TORCH_CHECK(dim == 1, "This kernel only supports dim=1");
    TORCH_CHECK(input.dim() == 3, "Input must be 3D tensor");

    auto sizes = input.sizes();
    const int batch_size = sizes[0];
    const int dim1 = sizes[1];
    const int dim2 = sizes[2];

    auto options = torch::TensorOptions()
        .dtype(torch::kLong)
        .device(input.device());

    torch::Tensor output = torch::empty({batch_size, dim2}, options);

    const dim3 grid(batch_size, dim2);
    const int block_size = 256;

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "argmin_dim1", ([&] {
        argmin_dim1_kernel<scalar_t><<<grid, block_size>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<int64_t>(),
            batch_size,
            dim1,
            dim2
        );
    }));

    return output;
}
"""

argmin_cpp = "torch::Tensor argmin_cuda(torch::Tensor input, int dim);"

argmin_ext = load_inline(
    name="argmin_ext",
    cpp_sources=argmin_cpp,
    cuda_sources=argmin_source,
    functions=["argmin_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self.argmin_cuda = argmin_ext.argmin_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.dim == 1 and x.is_cuda:
            return self.argmin_cuda(x, self.dim)
        return torch.argmin(x, dim=self.dim)
